 if(action==='fields'||action==='artwork'){smartCloseLaunch();$('studio-modal')?.close();tab=action==='fields'?'fields':'artwork';render();}else if(action==='switch-character'||action==='campaign-library'){smartCloseLaunch();openCampaignLauncher();}else if(action==='backups')smartBackupPanel();else if(action==='cloud-backup'||action==='cloud-restore'){if(smartMode!=='connected'||!cloudStore?.user){smartAuthMessage='Sign in to use cloud backups.';smartShow('entry');}else if(action==='cloud-backup')await cloudSavePrompt();else await cloudLibrary();}else if(action==='backup-download'){download(JSON.stringify(SmartFiles.portable(model),null,2),(v('CharacterName')||'Character')+'_Legendfolio_Backup.json','application/json');notify('Complete character backup downloaded.');}else if(action==='backup-restore')smartFileInput('smart-restore-file','application/json,.json',smartStageRestore).click();else if(action==='backup-apply'){b.disabled=true;await smartApplyRestore();}else if(action==='sheet-export')await smartExportSheet();else if(action==='summary-sheet')await smartSummaryPDF();else if(action==='template-editor')await smartTemplateEditor();else if(action==='template-upload')smartFileInput('smart-template-file','application/pdf,.pdf',smartTemplateUpload).click();else if(action==='template-save'){b.disabled=true;try{await smartSaveTemplate();}finally{b.disabled=false;}}else if(action==='print'){smartCloseLaunch();$('studio-modal')?.close();requestAnimationFrame(()=>window.print());}else if(action==='campaign-tools')smartCampaignTools();else if(action==='tour'){smartCloseLaunch();modernStartTour(true);}const strip=$('smart-utilities');if(strip)strip.open=false;
