const smartPreviousGuideSteps=modernGuideSteps;
modernGuideSteps=function(role){const steps=smartPreviousGuideSteps(role).map(row=>[...row]);const phone=window.innerWidth<700,desktop=window.innerWidth>=1200;if(role==='Player'){steps[1][1]=phone?'Swipe through your character tools.':desktop?'Your actions live in the header.':'Your tools live in the side rail.';steps[1][2]=phone?'Swipe the bottom navigation to reach Actions, Party, Skills, Inventory, Spells, Relationships and Journal.':desktop?'Hover or focus an icon to see its name. Actions, Party, Skills, Inventory, Spells, Relationships and Journal stay in a consistent order.':'The side rail keeps all seven gameplay destinations visible and labelled.';}else{steps[2][2]='Launch DM Studio from the Hub. This opens the DM tools; connected campaigns still require your authenticated account to own or administer them.';}steps[steps.length-1][2]='Open the utility strip for Backup & Export, Return to Hub and Settings. Studio Settings contains appearance, account connections, recovery tools and Studio Guide. You can replay this tour there.';return steps;};
