function smartLastBackup(){const user=smartMode==='connected'&&cloudStore?.user,link=user?model.cloudLinks?.[user.id]:null;if(!link)return 'No cloud backup is linked to this character.';try{const values=JSON.parse(localStorage.getItem(smartKey+'-backup-times:'+user.id)||'{}'),date=values[link.id];if(date)return 'Last successful backup: '+new Date(date).toLocaleString();}catch{}return 'Cloud revision '+link.revision+' · backup time is not recorded on this device.';}
const smartPreviousCloudWrite=cloudWrite;
cloudWrite=async function(...args){const id=cloudStore?.user?.id,character=campaignLibrary?.activeCharacter,before=id?model.cloudLinks?.[id]:null;try{return await smartPreviousCloudWrite(...args);}finally{const after=id&&cloudStore?.user?.id===id&&campaignLibrary?.activeCharacter===character?model.cloudLinks?.[id]:null;if(after&&(!before||before.id!==after.id||before.revision!==after.revision)){try{const key=smartKey+'-backup-times:'+id,values=JSON.parse(localStorage.getItem(key)||'{}');values[after.id]=Date.now();localStorage.setItem(key,JSON.stringify(values));}catch{}}}};

const smartPreviousReset=resetCampaignDashboard;
resetCampaignDashboard=function(closeCloud,...args){if(closeCloud&&smartHasDOM()){smartTemplateSequence++;smartTemplateDraft=null;smartTemplateScope=null;const title=$('modal-title')?.textContent;if(['Campaign character sheet','Your user profile'].includes(title)){$('studio-modal')?.close();if($('modal-content'))$('modal-content').textContent='';}smartProfileSource=null;smartProfileDraft=null;smartProfileScope='';smartProfileLoading='';smartProfile=SmartPlay.profile();}return smartPreviousReset(closeCloud,...args);};

const smartPreviousAbout=uiAbout;
uiAbout=function(...args){const result=smartPreviousAbout(...args),content=$('modal-content');if(content?.insertAdjacentHTML)content.insertAdjacentHTML('afterbegin','<section class="control-tools-section"><h3>Build 60 · Navigation alignment</h3><p>Player navigation stays separate from DM Studio at every screen width. Tablet icons and labels share consistent spacing and alignment; older duplicate tabs stay in Campaign companion.</p><h3>Build 59 · SMART PLAY</h3><p>A new Main Menu, Studio Hub profiles, adaptive icon navigation, Studio Settings and Backup & Export. Interface Level follows character selection. DM Studio launches from the Hub.</p></section>');const date=content?.querySelector('.ui-about>.hint');if(date)date.textContent='SMART PLAY · Build 60 · 22 October 2026';return result;};

async function smartAuthLink(){const url=new URL(location.href),kind=url.searchParams.get('auth');if(!['verify','recovery'].includes(kind)||!(url.searchParams.has('code')||/access_token=/.test(url.hash)))return;const epoch=++smartAuthEpoch;try{await smartEnableCloud();if(epoch!==smartAuthEpoch||smartMode!=='connected')return;if(cloudStore?.user){try{localStorage.setItem(smartKey+'-remembered-account','true');}catch{}if(cloudRecovery){launchDialog().close();cloudAccountView();}else{smartAuthMessage='Your account is ready. Continue to your studio.';smartShow('entry');}}else{smartAuthMessage=kind==='recovery'?'This recovery link could not be verified. Request a new recovery email.':'Your email link has been processed. Sign in to continue.';smartShow('entry');}}catch(error){if(epoch!==smartAuthEpoch)return;smartAuthMessage='This account link could not be verified. Request a new email or sign in.';smartShow('entry');}}
async function smartFinishRecovery(){if(cloudBusy)return;const password=$('cloud-new-password')?.value||'';if(password.length<12)throw Error('Use at least 12 characters.');await cloudConnect();const a=cloudStore.account();cloudBusy=true;try{const{error}=await cloudClient.auth.updateUser({password});cloudStore.still(a);if(error)throw error;cloudRecovery=false;$('studio-modal')?.close();try{localStorage.setItem(smartKey+'-remembered-account','true');}catch{}await cloudStart();await smartStartup();}finally{cloudBusy=false;}}
document.addEventListener('click',async event=>{if(!smartHasDOM())return;const button=event.target.closest?.('button');if(button?.id!=='cloud-update-password')return;event.preventDefault();event.stopImmediatePropagation();button.disabled=true;try{await smartFinishRecovery();}catch(error){const message=$('cloud-account-message');if(message)message.textContent=error.message;else notify(error.message);}finally{if(button.isConnected)button.disabled=false;}},true);
